package com.procurement.compliance_engine.service;

import com.procurement.compliance_engine.dto.DocumentChecklistItem;
import com.procurement.compliance_engine.dto.OrganizationDocumentResponse;
import com.procurement.compliance_engine.entity.OrganizationDocument;
import com.procurement.compliance_engine.repository.BidderProfileRepository;
import com.procurement.compliance_engine.repository.OrganizationDocumentRepository;
import com.procurement.compliance_engine.repository.OrganizationRepository;
import com.procurement.compliance_engine.security.CurrentUser;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
import java.io.IOException;
import java.security.MessageDigest;
import java.time.OffsetDateTime;
import java.util.*;

@Service
public class OrganizationDocumentService {
 private final OrganizationDocumentRepository documents;private final OrganizationRepository organizations;private final BidderProfileRepository profiles;private final DocumentStorageService storage;private final JdbcTemplate jdbc;private final long maxBytes;private final boolean scanRequired;
 private static final Map<String,String> PATHS=Map.ofEntries(Map.entry("BUSINESS_REGISTRATION","registration"),Map.entry("PAN","tax/pan"),Map.entry("GST_CERTIFICATE","tax/gst"),Map.entry("SIGNATORY_AUTHORIZATION","legal/authorization"),Map.entry("ADDRESS_PROOF","legal/address-proof"),Map.entry("FINANCIAL_STATEMENT","financial"),Map.entry("CAPABILITY_DECLARATION","experience"),Map.entry("UDYAM_MSME","certifications"),Map.entry("ENTITY_DEED","legal/entity-deed"),Map.entry("EXPERIENCE_PROOF","experience"),Map.entry("ISO_CERTIFICATE","certifications"),Map.entry("SECTOR_LICENSE","licenses"),Map.entry("NON_BLACKLISTING","legal/declarations"),Map.entry("OTHER_STATUTORY","legal/statutory"),Map.entry("CERTIFICATE_OF_INCORPORATION","registration/incorporation"),Map.entry("COMPANY_PAN","tax/pan"),Map.entry("MOA","legal/moa"),Map.entry("AOA","legal/aoa"),Map.entry("AUTHORIZATION_LETTER","legal/authorization"),Map.entry("BANK_ACCOUNT_PROOF","banking"),Map.entry("REGISTERED_ADDRESS_PROOF","legal/address-proof"),Map.entry("SIGNATORY_IDENTITY_PROOF","legal/signatory-identity"),Map.entry("AUDITED_FINANCIAL_STATEMENTS","financial"),Map.entry("UDYAM_CERTIFICATE","certifications/udyam"),Map.entry("LLP_AGREEMENT","legal/llp-agreement"),Map.entry("DESIGNATED_PARTNER_ID","legal/partner-identity"),Map.entry("PARTNERSHIP_DEED","legal/partnership-deed"),Map.entry("FIRM_REGISTRATION_CERTIFICATE","registration/firm"),Map.entry("PARTNER_IDENTITY_PROOF","legal/partner-identity"),Map.entry("PROPRIETOR_IDENTITY_PROOF","legal/proprietor-identity"),Map.entry("BUSINESS_EXISTENCE_EVIDENCE","registration/business-existence"),Map.entry("SHOP_ESTABLISHMENT_CERTIFICATE","registration/shop-establishment"),Map.entry("BUSINESS_LICENSE","licenses/business"),Map.entry("SECTION_8_APPROVAL","registration/section-8-approval"),Map.entry("12AB_80G_CERTIFICATE","tax/12ab-80g"),Map.entry("GOVERNMENT_ESTABLISHMENT_PROOF","registration/government"),Map.entry("OFFICER_IDENTITY_PROOF","legal/officer-identity"),Map.entry("DELEGATION_LETTER","legal/delegation"),Map.entry("INDUSTRY_LICENSE","licenses/industry"));
 public OrganizationDocumentService(OrganizationDocumentRepository d,OrganizationRepository o,BidderProfileRepository p,DocumentStorageService s,JdbcTemplate jdbc,@Value("${app.storage.max-file-size-bytes:26214400}") long max,@Value("${app.storage.scan-required:true}") boolean scanRequired){this.documents=d;this.organizations=o;this.profiles=p;this.storage=s;this.jdbc=jdbc;this.maxBytes=max;this.scanRequired=scanRequired;}
 @Transactional public OrganizationDocumentResponse upload(String type,String financialYear,MultipartFile file){var actor=CurrentUser.get();if(actor==null||!"BIDDER".equals(actor.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Bidder account required");UUID orgId=actor.organizationId();var org=organizations.findById(orgId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Organization not found"));String category=canonicalDocumentType(type);if(!PATHS.containsKey(category))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported registration document category");String legalType=profiles.findByOrganizationId(orgId).map(com.procurement.compliance_engine.entity.BidderProfile::getEntityType).orElse(null);if(legalType==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Save company details before uploading documents");Boolean allowed=jdbc.query("SELECT EXISTS(SELECT 1 FROM legal_type_document_requirements WHERE legal_type_code=? AND document_type_code=? AND active)",rs->rs.next()&&rs.getBoolean(1),legalType,category);if(!Boolean.TRUE.equals(allowed))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This document type is not part of the selected company checklist");byte[] content=bytes(file);String checksum=sha256(content);String filename=safeFilename(file.getOriginalFilename());if(("FINANCIAL_STATEMENT".equals(category)||"AUDITED_FINANCIAL_STATEMENTS".equals(category))&&(financialYear==null||!financialYear.matches("20\\d{2}-20\\d{2}")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Financial year must use YYYY-YYYY format");UUID id=UUID.randomUUID();int version=documents.countByOrganizationIdAndDocumentType(orgId,category)+1;String versionId=UUID.randomUUID().toString();String key="organizations/"+orgId+"/"+PATHS.get(category)+"/"+id+"/"+versionId+".pdf";storage.put(key,content,"application/pdf",checksum);try{List<OrganizationDocument> prior=("FINANCIAL_STATEMENT".equals(category)||"AUDITED_FINANCIAL_STATEMENTS".equals(category))?documents.findByOrganizationIdAndDocumentTypeAndFinancialYearAndSupersededAtIsNull(orgId,category,financialYear):documents.findByOrganizationIdAndDocumentTypeAndSupersededAtIsNull(orgId,category);prior.forEach(d->d.setSupersededAt(OffsetDateTime.now()));OrganizationDocument d=new OrganizationDocument();d.setId(id);d.setOrganization(org);d.setUploadedBy(actor.id());d.setDocumentType(category);d.setFinancialYear(financialYear);d.setObjectKey(key);d.setStorageProvider(storage.provider());d.setBucketIdentifier(storage.bucketIdentifier());d.setOriginalFilename(filename);d.setContentType("application/pdf");d.setFileSize((long)content.length);d.setSha256Checksum(checksum);d.setVersion(version);d.setVerificationStatus("PENDING");d.setProcessingStatus(scanRequired?"QUARANTINED":"AVAILABLE");OrganizationDocument saved=documents.saveAndFlush(d);jdbc.update("INSERT INTO document_audit_events(actor_id,organization_id,document_id,event_type,outcome) VALUES (?,?,?,'DOCUMENT_UPLOADED','SUCCESS')",actor.id(),orgId,id);refreshOnboardingStatus(orgId);return OrganizationDocumentResponse.from(saved);}catch(RuntimeException e){storage.delete(key);throw e;}}
 @Transactional(readOnly=true) public List<OrganizationDocumentResponse> list(){var actor=CurrentUser.get();if(actor==null||!"BIDDER".equals(actor.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Bidder account required");return documents.findByOrganizationIdAndSupersededAtIsNullOrderByUploadedAtDesc(actor.organizationId()).stream().map(OrganizationDocumentResponse::from).toList();}
 @Transactional(readOnly=true) public byte[] download(UUID id){var actor=CurrentUser.get();if(actor==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required");UUID orgId="SYSTEM_ADMIN".equals(actor.role())?documents.findById(id).map(d->d.getOrganization().getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found")):actor.organizationId();var d=documents.findByIdAndOrganizationId(id,orgId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found"));if(d.getSupersededAt()!=null)throw new ResponseStatusException(HttpStatus.GONE,"Document version superseded");if(!"AVAILABLE".equals(d.getProcessingStatus()))throw new ResponseStatusException(HttpStatus.LOCKED,"Document is quarantined pending malware scanning");byte[] b=storage.get(d.getObjectKey());if(!sha256(b).equalsIgnoreCase(d.getSha256Checksum()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Document checksum mismatch");return b;}
 @Transactional(readOnly=true) public List<DocumentChecklistItem> checklist(){var actor=CurrentUser.get();if(actor==null||!"BIDDER".equals(actor.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Bidder account required");var profile=profiles.findByOrganizationId(actor.organizationId()).orElseThrow();return checklistFor(actor.organizationId(),profile);}
 @Transactional public void review(UUID id,String status,String reason){var actor=CurrentUser.get();if(actor==null||!"SYSTEM_ADMIN".equals(actor.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"System administrator required");if(!List.of("VERIFIED","REJECTED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Review status must be VERIFIED or REJECTED");OrganizationDocument d=documents.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found"));d.setVerificationStatus(status);d.setVerifiedBy(actor.id());d.setVerifiedAt(OffsetDateTime.now());d.setRejectionReason("REJECTED".equals(status)?reason:null);jdbc.update("INSERT INTO document_audit_events(actor_id,organization_id,document_id,event_type,outcome) VALUES (?,?,?,'DOCUMENT_REVIEWED',?)",actor.id(),d.getOrganization().getId(),id,status);refreshOnboardingStatus(d.getOrganization().getId());}
 private void refreshOnboardingStatus(UUID org){var profile=profiles.findByOrganizationId(org).orElse(null);if(profile==null)return;List<DocumentChecklistItem> items=checklistFor(org,profile);List<String> missing=items.stream().filter(DocumentChecklistItem::required).filter(i->i.alternativeGroup()==null&&!i.uploaded()).map(DocumentChecklistItem::documentType).toList();Map<String,List<DocumentChecklistItem>> groups=new HashMap<>();items.stream().filter(i->i.alternativeGroup()!=null).forEach(i->groups.computeIfAbsent(i.alternativeGroup(),k->new ArrayList<>()).add(i));boolean groupMissing=groups.values().stream().anyMatch(g->g.stream().anyMatch(DocumentChecklistItem::required)&&g.stream().noneMatch(DocumentChecklistItem::uploaded));if(!missing.isEmpty()||groupMissing)profile.setOnboardingStatus("DOCUMENTS_PENDING");else if(items.stream().filter(DocumentChecklistItem::required).anyMatch(i->"REJECTED".equals(i.status())))profile.setOnboardingStatus("REJECTED");else if(items.stream().filter(DocumentChecklistItem::required).allMatch(i->"VERIFIED".equals(i.status())))profile.setOnboardingStatus("VERIFIED");else profile.setOnboardingStatus("VERIFICATION_PENDING");}
 private List<DocumentChecklistItem> checklistFor(UUID org,com.procurement.compliance_engine.entity.BidderProfile p){if(p.getEntityType()==null)return List.of();Map<String,OrganizationDocument> current=new HashMap<>();documents.findByOrganizationIdAndSupersededAtIsNullOrderByUploadedAtDesc(org).forEach(d->current.putIfAbsent(d.getDocumentType(),d));List<Map<String,Object>> rules=jdbc.queryForList("SELECT r.document_type_code,r.requirement_level,r.condition_expression,r.alternative_group,r.sort_order,d.display_name FROM legal_type_document_requirements r JOIN document_types d ON d.code=r.document_type_code WHERE r.legal_type_code=? AND r.active AND d.active ORDER BY r.sort_order",p.getEntityType());List<DocumentChecklistItem> result=new ArrayList<>();for(var rule:rules){String type=(String)rule.get("document_type_code");String level=(String)rule.get("requirement_level");String condition=(String)rule.get("condition_expression");String group=(String)rule.get("alternative_group");boolean required="REQUIRED".equals(level)||("CONDITIONAL".equals(level)&&conditionApplies(condition,p));var doc=current.get(type);String status=doc==null?"MISSING":doc.getVerificationStatus();result.add(new DocumentChecklistItem(type,required,doc!=null,status,condition,(String)rule.get("display_name"),level,group));}return result;}
 private boolean conditionApplies(String condition,com.procurement.compliance_engine.entity.BidderProfile p){if(condition==null)return false;return switch(condition){case "gstApplicable=true"->p.isGstApplicable();case "firmRegistered=true"->p.isFirmRegistered();case "representativeIsDifferent"->!p.isRepresentativeIsSignatory();case "msmeBenefitClaimed"->p.isMsmeBenefitClaimed();case "shopRegistrationApplicable"->p.isShopRegistrationApplicable();case "businessLicenseAvailable"->p.isBusinessLicenseAvailable();case "isIncorporated=true"->p.isIncorporatedEntity();case "panApplicable=true"->p.isPanApplicable();case "section8TaxRegistrationApplicable"->p.isSection8TaxRegistrationApplicable();default->false;};}
 private String canonicalDocumentType(String type){String category=type.toUpperCase(Locale.ROOT);return switch(category){case "PAN"->"COMPANY_PAN";case "BUSINESS_REGISTRATION"->"CERTIFICATE_OF_INCORPORATION";case "SIGNATORY_AUTHORIZATION"->"AUTHORIZATION_LETTER";case "ADDRESS_PROOF"->"REGISTERED_ADDRESS_PROOF";case "ENTITY_DEED"->profiles.findByOrganizationId(CurrentUser.get().organizationId()).map(com.procurement.compliance_engine.entity.BidderProfile::getEntityType).filter("LLP"::equals).isPresent()?"LLP_AGREEMENT":"PARTNERSHIP_DEED";case "UDYAM_MSME"->"UDYAM_CERTIFICATE";case "FINANCIAL_STATEMENT"->"AUDITED_FINANCIAL_STATEMENTS";case "EXPERIENCE_PROOF"->"AUDITED_FINANCIAL_STATEMENTS";case "CAPABILITY_DECLARATION","ISO_CERTIFICATE","SECTOR_LICENSE","NON_BLACKLISTING","OTHER_STATUTORY"->category;default->category;};}
 private void refreshOnboardingStatus(){refreshOnboardingStatus(CurrentUser.get().organizationId());}
 private byte[] bytes(MultipartFile f){if(f==null||f.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A non-empty PDF is required");if(f.getSize()>maxBytes)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"File exceeds upload size limit");try{byte[] b=f.getBytes();if(b.length<5||b.length>maxBytes||!new String(b,0,Math.min(b.length,1024),java.nio.charset.StandardCharsets.ISO_8859_1).contains("%PDF-"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"File must contain a PDF signature");return b;}catch(IOException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Could not read upload",e);}}
 private static String safeFilename(String n){if(n==null||n.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Filename required");String b=n.replace('\\','/');b=b.substring(b.lastIndexOf('/')+1).replaceAll("[\\p{Cntrl}]","").trim();if(b.isBlank()||b.length()>255)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid filename");return b;}
 private static String sha256(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}}
}
